steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": {
      "issues": {
        "filter": {
          "title": {
            "contains": "Checkout crash on Safari"
          }
        },
        "first": 10,
        "nodes": {
          "id",
          "identifier",
          "title",
          "url",
          "estimate",
          "attachments": {
            "first": 10,
            "nodes": {
              "id",
              "title",
              "url",
              "creator": {
                "id",
                "name"
              }
            }
          }
        }
      }
    }
  }'
